<script setup lang="ts">
import { t as uiText } from '@/locales'

import { computed, onMounted, reactive, ref, watch, nextTick } from 'vue'
import { ElMessage,ElMessageBox } from 'element-plus'
import { useRouter,useRoute } from 'vue-router'
import {useCollaborationWorkspace} from '@/stores/collaborationWorkspace'
import {locationNames} from '@/utils/collaboration'
import { getMoldTargetOptions } from '@/api/modules/moldApplications'
import { useUserStore } from '@/stores/user'
import * as api from '@/api/modules/marketWatch'
import * as moldApi from '@/api/modules/moldApplications'
import { getCollaborationOptions } from '@/api/modules/collaboration'
import { getPhoneBrands } from '@/api/modules/phoneReference'
import MarketArchivePanel from '@/views/collaboration/MarketArchivePanel.vue'
import PhoneProductCoverage from './components/PhoneProductCoverage.vue'
import ProductSalesCatalog from '@/components/ProductionMetadata/ProductSalesCatalog.vue'
import MoldHistoryReconciliation from '@/views/mold-applications/components/MoldHistoryReconciliation.vue'
import MoldApplicationEditor from '@/views/mold-applications/components/MoldApplicationEditor.vue'
import SharedCompatiblePhoneSelector from '@/views/mold/components/SharedCompatiblePhoneSelector.vue'
import {toArchivedProductRoute,toArchivedSkuRoute} from '@/utils/projectRoute'
import {phoneCoverageNames as states,moldReviewTarget,moldReviewActionName} from '@/utils/phoneCoverage'
import type { MoldOpportunityView, MarketPhoneModel, MarketPhoneCoverageState, MarketPhoneQuery, MarketPhonePage, MarketWatchConfig, MarketPhoneMold, MarketPhoneProduct } from '@/types/marketWatch'
import type { CompatiblePhone, PhoneBrand } from '@/types/molds'
import type { ProductLineOption } from '@/types/collaboration'

const router=useRouter(),route=useRoute(), user=useUserStore(),workspace=useCollaborationWorkspace()
function approvalLabel(status?:string,coverageState?:string){return moldApi.moldBusinessStatusNames[status as moldApi.MoldBusinessStatus]||label(coverageState||status||'approval_unknown')}
const config=ref<MarketWatchConfig>(), result=ref<MarketPhonePage>(), loading=ref(false), syncing=ref(false), reconciling=ref(false), error=ref('')
const brands=ref<PhoneBrand[]>([]), productLines=ref<ProductLineOption[]>([]), canCreate=ref(false)
const query=reactive<MarketPhoneQuery>({page:1,size:50,opportunityView:'opportunities'}), moreFilters=ref(false)
const detailVisible=ref(false), detail=ref<MarketPhoneModel>(), detailLoading=ref(false), detailError=ref('')
const matchVisible=ref(false), matching=ref(false), matchRow=ref<MarketPhoneModel>(), selectedPhones=ref<number[]>([]), phoneOptions=ref<CompatiblePhone[]>([]), matchReason=ref(''), matchError=ref('')
const pricesRefreshing=ref(false)
async function retryPrices(){if(pricesRefreshing.value)return;pricesRefreshing.value=true;const token=user.token;try{let status=await api.refreshMarketPrices(true);for(let i=0;status.refreshing&&i<60&&token===user.token;i++){await new Promise(resolve=>setTimeout(resolve,i<5?2000:10000));if(token!==user.token)return;status=await api.refreshMarketPrices(false)}if(token!==user.token)return;if(status.error)throw new Error(status.error);if(status.refreshing){ElMessage.info(uiText('报价仍在后台补采，稍后刷新来源查看'));return}await refresh();if(detailVisible.value&&detail.value)await open(detail.value)}catch(e){if(token===user.token){detailError.value=message(e);if(!detailVisible.value)error.value=message(e)}}finally{if(token===user.token)pricesRefreshing.value=false}}
const starting=ref(''),startVisible=ref(false),startRow=ref<MarketPhoneModel>(),startExisting=ref<moldApi.MoldApplication>(),startProduct=ref<number>(),startIntent=ref<'new'|'new_set'>('new_set'),startTarget=ref<number>(),startReason=ref(''),startRequestId=ref(''),startTargets=ref<moldApi.MoldTargetOptions>({projects:[],items:[]}),startSubmission=ref<moldApi.StartMoldApplication>(),startError=ref('')
const requests=new Map<string,string>(),failedImages=ref(new Set<string>())
function requestId(key:string){let id=requests.get(key);if(!id){id=crypto.randomUUID();requests.set(key,id)}return id}
let generation=0, detailGeneration=0
const rows=computed(()=>result.value?.content||[]), stats=computed(()=>result.value?.stats)
const canMatch=computed(()=>!!result.value?.capabilities.canMatch)
const canMaintain=computed(()=>!!result.value?.capabilities.canMaintainReference)
function label(state:string){return states[state as MarketPhoneCoverageState]||(moldApi.moldBusinessStatusNames as Record<string,string>)[state]||state}
function date(value:string|null|undefined){if(!value)return '—';const d=new Date(value);return Number.isNaN(d.getTime())?value:new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit'}).format(d)}
function image(row:MarketPhoneModel){return row.images?.find(url=>!failedImages.value.has(url))||''}
function failImage(url:string){if(url)failedImages.value.add(url)}
function openProduct(product:MarketPhoneProduct){detailVisible.value=false;return router.push(product.productType==='sku'?toArchivedSkuRoute(product.productId):toArchivedProductRoute(product.productId))}
async function reconcile(){if(reconciling.value)return;const token=user.token;reconciling.value=true;error.value='';try{const result=await api.reconcileMarketWatchPhones();if(token!==user.token)return;workspace.changed();ElMessage.success(uiText('已补齐 {value0} 条来源关联；有明确依据的资料已自动关联',{value0:(result.changedSources)}));await load()}catch(e){if(token===user.token)error.value=message(e)}finally{if(token===user.token)reconciling.value=false}}
function message(e:unknown){return e instanceof Error?e.message:'读取失败，请重试'}
function activeApplication(row:MarketPhoneModel){return row.coverages.flatMap(c=>c.applications).find(a=>!['terminated','refused','rejected','withdrawn'].includes(a.businessStatus))}
async function load(){const epoch=++generation,token=user.token;loading.value=true;error.value='';try{const q={...query,keyword:query.keyword?.trim()||undefined};const next=await api.getMarketWatchItems(q);if(epoch!==generation||token!==user.token)return;const summary=await api.getMarketWatchSummary(q);if(epoch===generation&&token===user.token)result.value={...next,...summary}}catch(e){if(epoch===generation&&token===user.token)error.value=message(e)}finally{if(epoch===generation&&token===user.token)loading.value=false}}
function filter(){query.page=1;void load()}
function reset(){Object.assign(query,{page:1,keyword:'',brandId:undefined,country:undefined,productLineId:undefined,coverageState:undefined,matchState:undefined,opportunityView:'opportunities'});void load()}
const statusNames:Record<string,string>={to_apply:'待开模',applied:'已申请',making:'开模中',partially_molded:'部分产品已开模',molded:'已开模',not_planned:'不计划开模',identity_unresolved:'手机身份待补'}
const views:{value:MoldOpportunityView;label:string}[]=[{value:'opportunities',label:'开发缺口'},{value:'to_apply',label:'待开模'},{value:'applied',label:'已申请'},{value:'making',label:'开模中'},{value:'partially_molded',label:'部分产品已开模'},{value:'molded',label:'已开模'},{value:'not_planned',label:'不计划开模'},{value:'all',label:'全部'}]
const historyReview=ref(false),salesCatalogVisible=ref(false),archiveVisible=ref(false)
async function archive(itemId?:number){archiveVisible.value=true;await router.replace({path:'/market-watch',query:{panel:'market-data',...(itemId?{itemId}:{}),...(route.query.productLineId?{productLineId:route.query.productLineId}:{})}})}
watch(archiveVisible,v=>{if(!v&&route.query.panel==='market-data')void router.replace({path:'/market-watch'})})
const priceKinds:Record<string,string>={retail:'完整售价',starting:'官网起售价',listed:'标价／缺货参考',launch:'官方发布价'}
function displayPrice(row:MarketPhoneModel){return row.preferredPrice??row.mexicoPrice??row.prices?.[0]}
function priceBrief(row:MarketPhoneModel){const p=displayPrice(row);if(!p)return '';const specs=[...new Set((p.specs||'').match(/\b(?:[45]G|\d{1,4}\s*(?:GB|TB))\b/gi)||[])];const prefix=p.kind!=='retail'?(priceKinds[p.kind]||'参考价'):p.currency==='CNY'?'人民币参考':p.currency!=='MXN'?'其他原币参考':'';return [prefix,specs.length?specs.join(' / '):p.source].filter(Boolean).join(' · ')}
function priceText(row:MarketPhoneModel){const p=displayPrice(row);return p?`${p.currency==='CNY'?'CNY ¥':p.currency+' '}${new Intl.NumberFormat('es-MX',{maximumFractionDigits:2}).format(p.amount)}${p.kind==='starting'?' 起':''}`:'暂未取得核实价格'}
async function plan(row:MarketPhoneModel){if(!row.phoneModelId)return;try{const next=row.moldPlanStatus==='not_planned'?'planned':'not_planned';if(next==='not_planned'&&row.hasActiveExecution){await open(row);ElMessage.warning(uiText('存在审批或制作，请先从详情进入原工程处理入口'));return}const input=await ElMessageBox.prompt(uiText('填写计划调整原因，历史开模覆盖会保留。'),next==='planned'?uiText('恢复开模计划'):uiText('登记不计划开模'),{inputType:'textarea',inputPattern:/\S+/,inputErrorMessage:uiText('请填写原因')});await api.updatePhoneMoldPlan(row.phoneModelId,{status:next,originalStatus:row.moldPlanStatus||'planned',reason:input.value.trim()});workspace.changed()}catch(e){if(e!=='cancel'&&e!=='close')ElMessage.error(message(e))}}

function viewFilter(value:MoldOpportunityView){query.opportunityView=value;filter()}
const applicationEditor=ref<InstanceType<typeof MoldApplicationEditor>>(),editingId=ref<number>(),submittedId=ref<number>()
let editorEpoch=0
async function editApplication(id?:number){const epoch=++editorEpoch,auth=user.token;try{const row=id?await moldApi.getMoldApplication(id):undefined;if(epoch!==editorEpoch||auth!==user.token)return;if(row&&row.status!=='draft'){await openApplication(row.applicationId);return}await applicationEditor.value?.open(row);if(auth===user.token&&epoch===editorEpoch){editingId.value=id;detailVisible.value=false}}catch(e){if(auth===user.token)error.value=message(e)}}
async function saved(id:number){editingId.value=id;await router.replace({path:'/market-watch',query:{applicationId:id,edit:'1'}})}
async function closeApplication(){++editorEpoch;editingId.value=undefined;if(route.query.applicationId||route.query.new||route.query.phoneModelId)await router.replace({path:'/market-watch'})}
async function submitted(id:number){submittedId.value=id;await closeApplication();await load()}
async function openRoute(){if(route.query.panel==='market-data')archiveVisible.value=true;if(route.query.panel==='products')salesCatalogVisible.value=true;if(!canCreate.value)return;const id=Number(route.query.applicationId);if(Number.isSafeInteger(id)&&id>0){if(editingId.value!==id)await editApplication(id);return}if(route.query.new==='1'){await editApplication();return}const phone=Number(route.query.phoneModelId);if(Number.isSafeInteger(phone)&&phone>0){try{const row=await api.getMarketWatchModel(typeof route.query.sourceModelKey==='string'?route.query.sourceModelKey:`phone:${phone}`);await start(row)}catch(e){error.value=message(e)}}}
watch(()=>route.fullPath,()=>{if(route.path==='/market-watch')void openRoute()})
function primaryLabel(row:MarketPhoneModel){const app=activeApplication(row);return app?.status==='draft'?'继续草稿':app?'查看申请进度':row.coverages.some(c=>c.molds.length)?'查看模具':row.openedProductCount?'查看覆盖／新增套':'发起开模申请'}
async function primaryAction(row:MarketPhoneModel){const app=activeApplication(row);if(app?.status==='draft'){await start(row);return}if(app){await openApplication(app.applicationId);return}if(row.coverages.some(c=>c.molds.length)||row.openedProductCount){await open(row);return}await start(row)}
async function refresh(){const token=user.token;syncing.value=true;error.value='';try{await api.refreshMarketWatchProjection();if(token===user.token)await load()}catch(e){if(token===user.token)error.value=message(e)}finally{if(token===user.token)syncing.value=false}}
async function open(row:MarketPhoneModel){const epoch=++detailGeneration,token=user.token;detailVisible.value=true;detail.value=row;detailLoading.value=true;detailError.value='';try{const next=await api.getMarketWatchModel(row.rowKey);if(epoch===detailGeneration&&token===user.token)detail.value=next}catch(e){if(epoch===detailGeneration&&token===user.token)detailError.value=message(e)}finally{if(epoch===detailGeneration&&token===user.token)detailLoading.value=false}}
function match(row:MarketPhoneModel){matchRow.value=row;selectedPhones.value=row.phoneModelId?[row.phoneModelId]:[];phoneOptions.value=row.candidatePhones||[];matchReason.value='';matchError.value='';matchVisible.value=true}
function selectPhone(phones:CompatiblePhone[]){if(phones.length>1){selectedPhones.value=phones.slice(-1).map(p=>p.phoneModelId);phoneOptions.value=phones.slice(-1)}else phoneOptions.value=phones}
async function saveMatch(){const row=matchRow.value,id=selectedPhones.value[0],token=user.token;if(!row||!id)return ElMessage.warning(uiText('请选择一款标准手机'));if(row.phoneModelId&&row.phoneModelId!==id&&!matchReason.value.trim())return ElMessage.warning(uiText('更正已有匹配请填写原因'));matching.value=true;matchError.value='';try{for(const source of row.sources)await api.linkMarketWatchPhoneModel(source.kind,source.id,{phoneModelId:id,originalPhoneModelId:source.phoneModelId,reason:matchReason.value.trim()||'人工核对市场来源手机'});if(token!==user.token)return;matchVisible.value=false;detailVisible.value=false;workspace.changed();ElMessage.success(uiText('已关联标准手机，模具适配仍须单独确认'));await load()}catch(e){if(token===user.token){matchError.value=message(e);await load()}}finally{if(token===user.token)matching.value=false}}
async function start(row:MarketPhoneModel,productLineId=query.productLineId){if(!row.phoneModelId){match(row);return}if(starting.value)return;const token=user.token;starting.value=row.rowKey;try{const result=await moldApi.startMoldApplication({phoneModelId:row.phoneModelId,sourceModelKey:row.rowKey,productLineId,requestId:requestId('default:'+row.phoneModelId+':'+(productLineId||'all'))});if(token!==user.token)return;if(result.requiresExplicitIntent){startRow.value=row;startExisting.value=result.applicationId?{...result,applicationId:result.applicationId}:undefined;startProduct.value=productLineId||startExisting.value?.productLineId||undefined;startIntent.value='new_set';startReason.value='';startTarget.value=undefined;startRequestId.value=crypto.randomUUID();startSubmission.value=undefined;startError.value='';startVisible.value=true;await loadStartTargets();return}if(!result.applicationId)throw new Error('申请返回缺少记录编号，请刷新核对');workspace.changed();detailVisible.value=false;await editApplication(result.applicationId);await saved(result.applicationId)}catch(e){if(token===user.token){error.value=message(e);ElMessage.error(error.value)}}finally{if(token===user.token)starting.value=''}}
async function focusCoverage(id:number){const coverage=detail.value?.coverages.find(c=>c.productLineId===id);const hasEvidence=coverage&&(coverage.molds.length||coverage.applications.length||coverage.products?.length);if(!hasEvidence&&detail.value&&canCreate.value&&detail.value.phoneModelId){await start(detail.value,id);return}const section=document.getElementById(`phone-product-${id}`);if(section){(section as HTMLDetailsElement).open=true;await nextTick();section.scrollIntoView({behavior:'smooth',block:'start'})}}
async function loadStartTargets(){startTargets.value={projects:[],items:[]};if(!startRow.value?.phoneModelId||!startProduct.value)return;const token=user.token,id=startRow.value.phoneModelId,product=startProduct.value;try{const result=await getMoldTargetOptions(id,product);if(token===user.token&&startProduct.value===product)startTargets.value=result}catch(e){if(token===user.token)startError.value=message(e)}}
async function explicitStart(){if(!startRow.value?.phoneModelId||!startProduct.value||!startReason.value.trim()||(startIntent.value==='new_set'&&!startTarget.value)){startError.value='请选择产品、已有主档（新增套时）并填写原因';return}if(starting.value)return;const token=user.token;starting.value=startRow.value.rowKey;startError.value='';try{if(!startSubmission.value)startSubmission.value={phoneModelId:startRow.value.phoneModelId,sourceModelKey:startRow.value.rowKey,productLineId:startProduct.value,executionIntent:startIntent.value,targetItemId:startIntent.value==='new_set'?startTarget.value:null,executionReason:startReason.value.trim(),newApplication:true,requestId:startRequestId.value};const result=await moldApi.startMoldApplication(startSubmission.value);if(token!==user.token)return;if(!result.applicationId)throw new Error('新申请尚未建立，请核对已有记录');workspace.changed();startVisible.value=false;await editApplication(result.applicationId);await saved(result.applicationId)}catch(e){if(token===user.token)startError.value=message(e)}finally{if(token===user.token)starting.value=''}}
watch(startProduct,()=>void loadStartTargets())
function setProductOptions(value:Awaited<ReturnType<typeof getCollaborationOptions>>){productLines.value=value.productLines.filter(p=>(p as ProductLineOption&{salesStatus?:string}).salesStatus==='on_sale')}
let productOptionsEpoch=0
async function refreshProductOptions(){const epoch=++productOptionsEpoch,auth=user.token;try{const value=await getCollaborationOptions();if(epoch===productOptionsEpoch&&auth===user.token)setProductOptions(value)}catch(e){if(auth===user.token)error.value=message(e)}}
watch(()=>workspace.revision,()=>{if(user.token){void refreshProductOptions();void load();if(detailVisible.value&&detail.value)void open(detail.value)}})
function openApplication(id:number){detailVisible.value=false;return router.push({path:'/mold-applications',query:{applicationId:id}})}
function openMold(mold:MarketPhoneMold,phoneModelId:number|null){detailVisible.value=false;return router.push(moldReviewTarget(mold,phoneModelId))}
async function setup(){const token=user.token;const values=await Promise.allSettled([api.getMarketWatchConfig(),getPhoneBrands({page:1,size:100,status:'enabled'}),getCollaborationOptions(),moldApi.getMoldOptions()]);if(token!==user.token)return;if(values[0].status==='fulfilled')config.value=values[0].value;if(values[1].status==='fulfilled')brands.value=values[1].value.content;if(values[2].status==='fulfilled')setProductOptions(values[2].value);if(values[3].status==='fulfilled')canCreate.value=values[3].value.canCreate;await load();await openRoute()}
watch(()=>user.token,()=>{++generation;++detailGeneration;++editorEpoch;editingId.value=undefined;submittedId.value=undefined;result.value=undefined;config.value=undefined;detail.value=undefined;detailVisible.value=false;matchVisible.value=false;canCreate.value=false;brands.value=[];productLines.value=[];loading.value=false;syncing.value=false;starting.value='';matching.value=false;startVisible.value=false;startExisting.value=undefined;requests.clear();failedImages.value.clear()})
onMounted(setup)
</script>

<template>
  <main class="market-watch" :aria-label='uiText("开模申请市场机型")'>
    <header class="page-head"><h2>{{ uiText("开模申请") }}</h2><span class="total">{{ uiText("共 ") }}{{result?.totalElements||0}}{{ uiText(" 款") }}</span><div class="actions"><el-button size="small" @click="router.push('/mold-applications')">{{ uiText("开模申请进度") }}</el-button><el-popover placement="bottom-end" trigger="click" :width="160" :persistent="false"><template #reference><el-button size="small">{{ uiText("资料与来源") }}</el-button></template><div class="secondary-actions"><el-button v-if="canMaintain" size="small" text @click="router.push({path:'/phone-model-codes'})">{{ uiText("手机编码资料") }}</el-button><el-button v-if="user.hasPermission('mold-application:convert')" size="small" text @click="historyReview=true">{{ uiText("历史补链与缺项") }}</el-button><el-button v-if="canMaintain" size="small" text @click="salesCatalogVisible=true">{{ uiText("在售产品与审批别名") }}</el-button><el-button size="small" text @click="archive()">{{ uiText("历史市场资料维护") }}</el-button><el-button v-if="canMatch" size="small" text :loading="reconciling" @click="reconcile">{{ uiText("一键关联手机资料") }}</el-button><el-button v-if="config?.enabled&&canMatch" size="small" text :loading="pricesRefreshing" @click="retryPrices">{{ uiText("批量更新手机价格") }}</el-button><el-button v-if="config?.enabled" size="small" text :loading="syncing" @click="refresh">{{ uiText("刷新来源") }}</el-button></div></el-popover><el-button v-if="canCreate" type="primary" size="small" @click="editApplication()">{{ uiText("手动发起申请") }}</el-button></div></header>
    <el-alert v-if="config&&!config.enabled" :title='uiText("市场来源同步已关闭，显示已缓存资料；仍可手动发起申请")' type="info" :closable="false"/>
    <el-alert v-if="submittedId" :title='uiText("开模申请已提交，可在申请进度查看审批及后续建档")' type="success" :closable="true" @close="submittedId=undefined"><el-button link @click="openApplication(submittedId!)">{{ uiText("查看申请进度") }}</el-button></el-alert>
      <section class="filters"><el-input v-model="query.keyword" size="small" clearable :placeholder='uiText("搜索手机／型号编码／产品／模具刻码")' @keyup.enter="filter"/><el-select v-model="query.productLineId" size="small" clearable filterable :placeholder='uiText("全部产品／款式")' @change="filter"><el-option v-for="line in productLines" :key="line.productLineId" :value="line.productLineId" :label="line.productName"/></el-select><el-button size="small" @click="moreFilters=!moreFilters" :aria-expanded="moreFilters">{{ uiText("更多筛选") }}</el-button><el-button size="small" type="primary" @click="filter">{{ uiText("查询") }}</el-button><el-button size="small" @click="reset">{{ uiText("重置") }}</el-button></section>
      <section v-if="moreFilters" class="advanced"><el-select v-model="query.coverageState" size="small" clearable :placeholder='uiText("实物／适配状态")' @change="filter"><el-option v-for="(name,key) in states" :key="key" :value="key" :label="name"/></el-select><el-select v-model="query.brandId" size="small" clearable filterable :placeholder='uiText("全部品牌")' @change="filter"><el-option v-for="b in brands" :key="b.brandId" :value="b.brandId" :label="b.name"/></el-select><el-select v-model="query.country" size="small" clearable :placeholder='uiText("来源国家／地区")' @change="filter"><el-option v-for="country in ['MX','CN','KR','GLOBAL']" :key="country" :value="country" :label="country"/></el-select><el-select v-model="query.matchState" size="small" clearable :placeholder='uiText("手机匹配状态")' @change="filter"><el-option value="matched" :label='uiText("已关联标准手机")'/><el-option value="unmatched" :label='uiText("待匹配")'/><el-option value="ambiguous" :label='uiText("匹配有歧义")'/></el-select></section>
      <section class="status-bar" role="tablist" :aria-label='uiText("开模机会视图")'><button v-for="view in views" :key="view.value" role="tab" :aria-selected="query.opportunityView===view.value" :class="[view.value,{active:query.opportunityView===view.value}]" @click="viewFilter(view.value)">{{uiText(String((view.label) ?? ''))}} {{stats?.opportunities?.[view.value]??(view.value==='all'?stats?.total||0:0)}}</button><span class="sync">{{ uiText("最后成功同步 ") }}{{date(result?.sync.lastSuccessAt)}}</span></section>
      <el-alert v-if="error||result?.sync.lastError" :title="error||uiText('来源同步失败：{value0}；当前显示上次成功同步资料',{value0:(result?.sync.lastError)})" type="error" :closable="false"><el-button link size="small" @click="error?load():refresh()">{{ uiText("重试") }}</el-button></el-alert>
      <p class="view-hint">{{ uiText("默认查看待开模和部分产品已开模；覆盖按在售产品计算。手机编码表示历史已申请，SKU 表示对应产品已有开模依据，实物适配及可复用分别查看。") }}<button v-if="canMaintain" class="text-link" @click="historyReview=true">{{ uiText("集中处理资料缺项") }}</button></p>
      <section class="ledger" role="table" :aria-label='uiText("手机及各产品模具覆盖")' v-loading="loading">
